+const test = require('node:test');
+const assert = require('node:assert');
+const { request } = require('../src/http');
+
+function replies(...statuses) {
+  const calls = [];
+  const fetchImpl = async (url) => { calls.push(url); return { status: statuses[calls.length - 1], ok: statuses[calls.length - 1] < 400 }; };
+  return { fetchImpl, calls };
+}
+
+test('a 503 is retried until it succeeds', async () => {
+  const { fetchImpl, calls } = replies(503, 503, 200);
+  const res = await request(fetchImpl, 'https://x.test/', { baseDelayMs: 0 });
+  assert.strictEqual(res.status, 200);
+  assert.strictEqual(calls.length, 3);
+});
+
+test('501 is not retried', async () => {
+  const { fetchImpl, calls } = replies(501, 200);
+  assert.strictEqual((await request(fetchImpl, 'https://x.test/', { baseDelayMs: 0 })).status, 501);
+  assert.strictEqual(calls.length, 1);
+});

